async function getProvingBlockId(provider, margin = 10) {
  const latest = await provider.getBlockNumber();
  return latest - margin;
}

// src/sdk_integration/approve-pool.ts
function buildApprovePoolCall(payrollAddress, tokenAddress, poolAddress, amount = (1n << 256n) - 1n) {
  const approveSelector = hash_exports.getSelectorFromName("approve");
  const { low, high } = cairo_exports.uint256(amount);
  const innerCalldata = [poolAddress, String(low), String(high)];
  return {
    contractAddress: payrollAddress,
    entrypoint: "execute",
    calldata: [
      "1",
      tokenAddress,
      approveSelector,
      String(innerCalldata.length),
      ...innerCalldata
    ]
  };
}

// src/sdk_integration/onboard.ts
function buildTransferCall(tokenAddress, recipient, amount) {
  const { low, high } = cairo_exports.uint256(amount);
  return { contractAddress: tokenAddress, entrypoint: "transfer", calldata: [recipient, String(low), String(high)] };
}
