// src/sdk_integration/wallet-account.ts
var WALLET_GLOBALS = {
  argent: ["starknet_argentX"],
  braavos: ["starknet_braavos"],
  xverse: ["starknet_xverse"],
  fordefi: ["starknet_fordefi", "fordefi"]
};
function getInjectedWallet(type) {
  if (type.startsWith("injected:")) {
    return window[type.slice("injected:".length)] ?? null;
  }
  const keys = WALLET_GLOBALS[type];
  if (!keys) return null;
  const w = window;
  for (const k of keys) {
    if (w[k]) return w[k];
  }
  return null;
}
function buildWalletAccount(provider, type, address) {
  const walletProvider = getInjectedWallet(type);
  if (!walletProvider) {
    throw new Error(
      `Cannot build WalletAccount: ${type} provider not found on window.`
    );
  }
  return new WalletAccount({
    provider,
    // The starknet.js types expect a StarknetWindowObject; injected wallets
    // satisfy it at runtime even though our `unknown` cast hides that here.
    walletProvider,
    address
  });
}

// src/sdk_integration/siws.ts
function loginTypedData(address, nonce) {
  return {
    types: {
      StarknetDomain: [
        { name: "name", type: "shortstring" },
        { name: "version", type: "shortstring" },
        { name: "chainId", type: "shortstring" },
        { name: "revision", type: "shortstring" }
      ],
      Login: [
        { name: "statement", type: "string" },
        { name: "address", type: "felt" },
        { name: "nonce", type: "string" }
      ]
    },
    primaryType: "Login",
    domain: { name: "PriPay", version: "1", chainId: SNIP12_CHAIN_ID, revision: "1" },
    message: {
      statement: "Sign in to PriPay to prove you own this wallet. This does not submit a transaction.",
      address,
      nonce
    }
  };
}
async function postJsonRetry(url, body, { timeoutMs = 25e3, attempts = 2 } = {}) {
  for (let attempt = 0; attempt < attempts; attempt++) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    try {
      return await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
        signal: ctrl.signal
      });
    } catch {
    } finally {
      clearTimeout(timer);
    }
  }
  throw new Error("Wallet login timed out \u2014 please try connecting again.");
}
async function walletSignIn(w, address) {
  const nRes = await postJsonRetry("/api/auth/nonce", { address });
  if (!nRes.ok) throw new Error("Could not start wallet login (HTTP " + nRes.status + ")");
  const { nonce } = await nRes.json();
  const typedData = loginTypedData(address, nonce);
  let signature;
  if (typeof w?.request === "function") {
    signature = await w.request({ type: "wallet_signTypedData", params: typedData });
  } else if (typeof w?.account?.signMessage === "function") {
    signature = await w.account.signMessage(typedData);
  } else {
    throw new Error("This wallet cannot sign the login message.");
  }
  const vRes = await postJsonRetry("/api/auth/verify", { address, signature, typedData }, { attempts: 1, timeoutMs: 35e3 });
  if (!vRes.ok) {
    let msg = "Wallet login failed";
    try {
      msg = (await vRes.json()).error || msg;
    } catch {
    }
    throw new Error(msg);
  }
}
async function walletSignOut() {
  try {
    await fetch("/api/auth/logout", { method: "POST" });
  } catch {
  }
}

