async function connectWithWallet(type) {
  setWalletErr("");
  document.querySelectorAll(".wallet-opt").forEach((b) => {
    b.disabled = true;
  });
  const walletBtn = document.getElementById("walletBtn");
  const walletLabel = document.getElementById("walletLabel");
  if (walletBtn) walletBtn.disabled = true;
  if (walletLabel) walletLabel.textContent = "Connecting...";
  try {
    if (type === "argent" || type === "braavos" || type === "xverse") {
      const KEY2 = { argent: "starknet_argentX", braavos: "starknet_braavos", xverse: "starknet_xverse" };
      const NAME = { argent: "Ready", braavos: "Braavos", xverse: "Xverse" };
      const w = window[KEY2[type]];
      if (!w) throw new Error(NAME[type] + " extension not detected. Install it and refresh.");
      let accounts;
      if (typeof w.request === "function") {
        accounts = await w.request({ type: "wallet_requestAccounts" });
      } else {
        await w.enable();
        accounts = [w.selectedAddress];
      }
      const addr = accounts?.[0] || w.selectedAddress;
      if (!addr) throw new Error("No address returned");
      await ensureExpectedChain(w, NAME[type]);
      await walletSignIn(w, addr);
      renderNetworkPill();
      onWalletConnected(addr, NAME[type], type);
    } else if (type === "metamask") {
      const eth = window.ethereum;
      if (!eth?.isMetaMask) throw new Error("MetaMask not detected. Install MetaMask and refresh.");
      try {
        await eth.request({ method: "wallet_getSnaps" });
      } catch {
        throw new Error("Your MetaMask version does not support Snaps. Update MetaMask to v11 or later.");
      }
      let snapResult;
      try {
        snapResult = await eth.request({ method: "wallet_requestSnaps", params: { [METAMASK_SNAP_ID]: {} } });
      } catch (e) {
        const rejected = e?.code === 4001 || /denied|rejected|permission/i.test(e?.message || "");
        throw new Error(rejected ? "Snap installation was rejected. Please approve the Starknet snap in the MetaMask popup and try again." : "Failed to install Starknet snap: " + (e?.message || e));
      }
      const installed = snapResult?.[METAMASK_SNAP_ID];
      if (installed?.error) throw new Error("Snap error: " + installed.error.message);
      let result;
      try {
        result = await eth.request({
          method: "wallet_invokeSnap",
          params: { snapId: METAMASK_SNAP_ID, request: { method: "starkNet_getStoredUserAccounts" } }
        });
      } catch {
        throw new Error("Could not fetch Starknet accounts from snap. Open the MetaMask Starknet snap and create an account first.");
      }
      const addr = Array.isArray(result) ? result[0]?.address : result?.address;
      if (!addr) throw new Error("No Starknet account found. Open the MetaMask Starknet snap and create an account first.");
      onWalletConnected(addr, "MetaMask", "metamask");
    } else if (type === "fordefi") {
      const w = window.starknet_fordefi || window.fordefi;
      if (!w) throw new Error("ForDefi extension not detected. Install it and refresh.");
      let accounts;
      if (typeof w.request === "function") {
        accounts = await w.request({ type: "wallet_requestAccounts" });
      } else {
        await w.enable();
        accounts = [w.selectedAddress];
      }
      const addr = accounts?.[0] || w.selectedAddress;
      if (!addr) throw new Error("No address returned");
      await ensureExpectedChain(w, "ForDefi");
      await walletSignIn(w, addr);
      renderNetworkPill();
      onWalletConnected(addr, "ForDefi", "fordefi");
    } else if (type.startsWith("injected:")) {
      const w = window[type.slice("injected:".length)];
      if (!w) throw new Error("Wallet not detected. Refresh and try again.");
      let accounts;
      if (typeof w.request === "function") {
        accounts = await w.request({ type: "wallet_requestAccounts" });
      } else {
        await w.enable();
        accounts = [w.selectedAddress];
      }
      const addr = accounts?.[0] || w.selectedAddress;
      if (!addr) throw new Error("No address returned");
      await ensureExpectedChain(w, w.name || "Wallet");
      await walletSignIn(w, addr);
      renderNetworkPill();
      onWalletConnected(addr, w.name || "Wallet", type);
    }
  } catch (err) {
    const msg = err?.message || String(err);
    const isPlainReject = err?.code === 4001 && !msg.includes("snap");
    if (!isPlainReject) setWalletErr(msg);
    if (walletBtn) walletBtn.disabled = false;
    if (walletLabel) walletLabel.textContent = "Connect wallet";
  } finally {
    document.querySelectorAll(".wallet-opt").forEach((b) => {
      b.disabled = false;
    });
  }
}

// src/pages/settings.ts
function renderSettings() {
  const statusEl = document.getElementById("setPmStatus");
  const addrEl = document.getElementById("setPmAddr");
  const btn = document.getElementById("setPmBtn");
  const clear = document.getElementById("setPmClear");
  const isAvnu = state.submitter instanceof AvnuPaymasterSubmitter;
  const hasPaymaster = state.submitter instanceof PrivateKeyPaymasterSubmitter;
  if (statusEl) {
    statusEl.textContent = isAvnu ? "AVNU paymaster (gasless)" : hasPaymaster ? "Configured (paste-key fallback)" : "Not configured";
    statusEl.style.color = isAvnu || hasPaymaster ? "#16a34a" : "var(--text3)";
  }
  if (addrEl) {
    const addr = hasPaymaster ? state.submitter.address : "";
    addrEl.textContent = addr;
    addrEl.style.display = addr ? "block" : "none";
  }
  if (btn) btn.textContent = hasPaymaster ? "Change paymaster key" : "Set paymaster key";
  if (clear) clear.style.display = hasPaymaster ? "inline" : "none";
  void renderAdminWallets();
}
async function renderAdminWallets() {
  const card = document.getElementById("adminWalletsCard");
  const list = document.getElementById("adminWalletsList");
  if (!card || !list) return;
  card.classList.toggle("hidden", !state.isAdmin);
  if (!state.isAdmin) return;
  let companies = [];
  try {
    const r = await fetch("/api/companies");
    companies = r.ok ? await r.json() : [];
  } catch {
    companies = [];
  }
  list.replaceChildren();
  if (!companies.length) {
    const empty = document.createElement("div");
    empty.style.cssText = "font-size:12px;color:var(--text3)";
    empty.textContent = "No wallets have connected yet.";
    list.appendChild(empty);
    return;
  }
  for (const { addr, company } of companies) {
    const row = document.createElement("div");
    row.style.cssText = "display:flex;align-items:center;gap:10px;justify-content:space-between;border:1px solid var(--border);border-radius:8px;padding:8px 12px";
    const info = document.createElement("div");
    info.style.cssText = "display:flex;flex-direction:column;gap:2px;min-width:0";
    const nameEl = document.createElement("div");
    nameEl.style.cssText = "font-size:13px;font-weight:500";
    nameEl.textContent = company && company.name ? company.name : "(company not set up)";
    const addrEl = document.createElement("div");
    addrEl.style.cssText = "font-size:11px;font-family:monospace;color:var(--text3);word-break:break-all";
    addrEl.textContent = addr;
    info.append(nameEl, addrEl);
    const btn = document.createElement("button");
    btn.className = "btn btn-p btn-sm";
    btn.textContent = "Edit";
    btn.addEventListener("click", () => openEditCompanyFor(addr, company));
    row.append(info, btn);
    list.appendChild(row);
  }
}
function submitPaymasterKey() {
  const addressEl = document.getElementById("pm-address");
  const keyEl = document.getElementById("pm-private-key");
  const statusEl = document.getElementById("pm-status");
  const errEl = document.getElementById("pm-err");
  if (!addressEl || !keyEl || !statusEl || !errEl) return;
  const address = addressEl.value.trim();
  const key = keyEl.value.trim();
  if (!address.startsWith("0x") || !key.startsWith("0x")) {
    if (!address.startsWith("0x")) flagInvalid("pm-address");
    if (!key.startsWith("0x")) flagInvalid("pm-private-key");
    errEl.style.display = "block";
    errEl.textContent = "Both address and private key must be 0x-prefixed hex.";
    statusEl.style.display = "none";
    return;
  }
  try {
    const account = new Account({ provider: state.provider, address, signer: key });
    state.submitter = new PrivateKeyPaymasterSubmitter(account, TOKENS.strk.address);
    keyEl.value = "";
    errEl.style.display = "none";
    statusEl.style.display = "none";
    renderSettings();
    closeM("paymasterKey");
  } catch (err) {
    errEl.style.display = "block";
    errEl.textContent = err?.message ?? String(err);
    statusEl.style.display = "none";
  }
}
async function configureAvnuPaymaster() {
  if (!PAYMASTER_FORWARDER) {
    console.info("[paymaster] no forwarder configured for this network \u2014 staying on the paste-key submitter");
    return;
  }
  if (!await paymasterAvailable()) return;
  state.submitter = new AvnuPaymasterSubmitter(POOL_FEE_TOKEN, PAYMASTER_FORWARDER);
  renderSettings();
}
async function loadLocalPaymaster() {
  try {
    const res = await fetch("paymaster.local.json");
    if (!res.ok) return;
    const cfg = await res.json();
    if (!cfg.address?.startsWith("0x") || !cfg.secretKey?.startsWith("0x")) return;
    const account = new Account({ provider: state.provider, address: cfg.address, signer: cfg.secretKey });
    state.submitter = new PrivateKeyPaymasterSubmitter(account, TOKENS.strk.address);
    renderSettings();
  } catch {
  }
}
function clearPaymaster() {
  state.submitter = new LocalSubmitter();
  renderSettings();
}
async function signHelloMessage() {
  const btn = document.getElementById("setSignDemoBtn");
  const result = document.getElementById("setSignDemoResult");
  if (!state.operatorAccount) {
    await showAlert("Connect a wallet first.", "SNIP-12 demo");
    return;
  }
  const typedData = {
    types: {
      StarknetDomain: [
        { name: "name", type: "shortstring" },
        { name: "version", type: "shortstring" },
        { name: "chainId", type: "shortstring" },
        { name: "revision", type: "shortstring" }
      ],
      Message: [{ name: "contents", type: "shortstring" }]
    },
    primaryType: "Message",
    domain: { name: "PriPay", version: "1", chainId: SNIP12_CHAIN_ID, revision: "1" },
    message: { contents: "hello world" }
  };
  if (btn) {
    btn.disabled = true;
    btn.textContent = "Check your wallet\u2026";
  }
  if (result) result.style.display = "none";
  try {
    const sig = await state.operatorAccount.signMessage(typedData);
    const parts = Array.isArray(sig) ? sig.map(String) : [String(sig)];
    if (result) {
      result.style.display = "block";
      result.textContent = "Signed \u2713\n" + parts.join("\n");
    }
  } catch (err) {
    const msg = err?.message || String(err);
    if (err?.code === 4001 || /reject|denied/i.test(msg)) {
      if (result) {
        result.style.display = "block";
        result.textContent = "Signature rejected in wallet.";
      }
    } else {
      await showAlert(msg, "SNIP-12 demo failed");
    }
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = "Sign hello message";
    }
  }
}

// src/pages/import.ts
